// Province names as they come from the MEAL lists → map name.
const strip = (s: string) => s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().replace(/[^A-Z]+/g, ' ').trim();
const ALIASES: Record<string, string> = {
  'MAPUTO': 'Maputo Província', 'MAPUTO PROVINCIA': 'Maputo Província', 'PROVINCIA DE MAPUTO': 'Maputo Província',
  'MAPUTO CIDADE': 'Maputo Cidade', 'CIDADE DE MAPUTO': 'Maputo Cidade', 'MAPUTO CITY': 'Maputo Cidade', 'CIDADE MAPUTO': 'Maputo Cidade',
  'ZAMBEZIA': 'Zambézia',
};

export function mapProvinceName(name: string): string | null {
  const key = strip(name).replace(/^PROVINCIA (DE |DO |DA )?/, '');
  if (ALIASES[key]) return ALIASES[key];
  return MOZ_PROVINCES.find((p) => strip(p.name) === key)?.name ?? null;
}
